final class MessageQueue<E> {
    private final ArrayDeque<E> q = new ArrayDeque<>();
    private final int cap;
    MessageQueue(int cap) { this.cap = cap; }

    synchronized void put(E e) throws InterruptedException {
        while (q.size() == cap) wait();   // releases the monitor lock
        q.addLast(e);
        notifyAll();
    }
}

